(function(){
function decode(value){if(!value)return null;try{var text=decodeURIComponent(Array.prototype.map.call(atob(value.replace(/-/g,'+').replace(/_/g,'/')),function(c){return '%'+('00'+c.charCodeAt(0).toString(16)).slice(-2);}).join(''));return JSON.parse(text);}catch(e){return null;}}
function encode(value){var bytes=unescape(encodeURIComponent(JSON.stringify(value)));return btoa(bytes).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function pageHref(child){var route=child&&child.route?String(child.route):'';if(route.charAt(0)==='/')return route;var slug=String(child&&child.slug||'').trim();if(!slug)return '';return '/baza/'+slug.split('/').map(function(part){return encodeURIComponent(part);}).join('/');}
function safeImage(value){var image=String(value||'');return image.charAt(0)==='/'||image.indexOf('https://')===0?image:'';}
document.querySelectorAll('.wf-instance[data-wf-component="kb-children"]').forEach(function(host){
if(host.dataset.kbReady==='true')return;
host.dataset.kbReady='true';
var list=host.querySelector('[data-kb-list]');
var status=host.querySelector('[data-kb-status]');
var form=host.querySelector('[data-kb-search]');
var query=host.querySelector('[data-kb-q]');
var section=host.querySelector('.wf-kb-children')||host;
if(!list)return;
function paint(data){
list.innerHTML='';
list.className='wf-kb-children__list';
var showImage=section.getAttribute('data-show-image')!=='false';
var showDescription=section.getAttribute('data-show-description')!=='false';
var title=document.createElement('h1');
title.className='wf-kb-children__title';
title.textContent=(data&&data.title)||'Baza znanja';
list.appendChild(title);
if(data&&data.intro){var intro=document.createElement('p');intro.className='wf-kb-children__intro';intro.textContent=data.intro;list.appendChild(intro);}
var items=(data&&data.children)||[];
if(!items.length){var empty=document.createElement('p');empty.className='wf-kb-children__empty';empty.textContent='Nema podređenih strana.';list.appendChild(empty);return;}
var grid=document.createElement('div');
grid.className='wf-kb-children__grid';
items.forEach(function(child){
var href=pageHref(child);
var card=href?document.createElement('a'):document.createElement('article');
if(href)card.href=href;
card.className='wf-kb-card';
if(showImage){
var media=document.createElement('div');
media.className='wf-kb-card__media';
var image=safeImage(child&&child.image);
if(image){var img=document.createElement('img');img.src=image;img.alt='';media.appendChild(img);}
card.appendChild(media);
}
var body=document.createElement('div');
body.className='wf-kb-card__body';
var heading=document.createElement('h2');
heading.className='wf-kb-card__title';
heading.textContent=(child&&(child.title||child.slug))||'';
body.appendChild(heading);
if(showDescription&&child&&child.description){var text=document.createElement('p');text.className='wf-kb-card__text';text.textContent=String(child.description);body.appendChild(text);}
card.appendChild(body);
grid.appendChild(card);
});
list.appendChild(grid);
}
function requestId(){var suffix=Math.random().toString(36).replace(/[^a-z0-9]/g,"").slice(0,8);var prefix=("00000000"+Date.now().toString(36)).slice(-8);return (prefix+suffix).slice(0,40);}
var pendingId="";
window.addEventListener("message",function(event){
if(event.source!==window.parent)return;
var data=event.data;
if(!data||data.type!=="elastyc-webfront-catalog-provider-result-v1")return;
if(data.requestId!==pendingId||data.instanceKey!==host.dataset.wfInstance)return;
if(!data.ok){if(status)status.textContent=data.error||"Strane trenutno nisu dostupne.";return;}
paint(data.data||{});
});
function load(){
var input=decode(host.dataset.wfProviderInput)||{};
var term=query?String(query.value||'').trim():'';
if(term){input.q=term;}else{delete input.q;}
if(!term){
var preview=decode(host.dataset.wfProviderPreview);
if(preview){paint(preview);return;}
var previewError=host.getAttribute("data-wf-provider-preview-error");
if(previewError){if(status)status.textContent=previewError;return;}
}
if(window.parent!==window){
pendingId=requestId();
window.parent.postMessage({type:"elastyc-webfront-catalog-provider-v1",pageKey:host.dataset.wfPage||"",instanceKey:host.dataset.wfInstance||"",input:input,requestId:pendingId},"*");
return;
}
var url=host.dataset.wfProviderUrl;
if(!url){if(status)status.textContent='Nema podređenih strana.';return;}
var targetUrl=new URL(url,window.location.href);
targetUrl.searchParams.set('wf_input',encode(input));
fetch(targetUrl.toString(),{credentials:'same-origin',headers:{Accept:'application/json'}}).then(function(response){if(!response.ok)throw new Error('HTTP '+response.status);return response.json();}).then(function(payload){paint(payload&&payload.data?payload.data:payload);}).catch(function(){if(status)status.textContent='Strane trenutno nisu dostupne.';});
}
if(form){form.addEventListener('submit',function(event){event.preventDefault();load();});}
load();
});
})();
